extends CharacterBody3D
## Hari in 3D: camera-relative walking on the XZ plane, a billboard image per state.
## Reads keys through Controls, reports to the logic only through Story's thin interface
## (player_x, set_moving) and shows Story.hari_state.

const Spec = preload("res://logic/hari_spec.gd")
const Billboard = preload("res://scenes/billboard_art.gd")
const ART_DIR := "res://assets/art/hari/"    ## <state_lower>.png, e.g. idle.png, keys.png
const ACCEL := 9.0                           ## m/s^2: ~0.25 s to full walking speed
const DECEL := 14.0                          ## m/s^2: settles in ~0.15 s
const STRIDE_M := 0.42                       ## distance per walk frame (feet don't slide)
const BOB_M := 0.035                         ## step bob height at full speed
const BREATH_HZ := 0.28                      ## idle breathing
const BREATH_AMOUNT := 0.007
const TURN_SECONDS := 0.14                   ## squash when facing flips

var _walk_frames: Array[String] = []
var _travel := 0.0
var _time := 0.0
var _turn := 0.0
var _facing_left := false

var camera: Camera3D
@onready var sprite: Billboard = $Sprite
@onready var label: Label3D = $StateLabel
@onready var collision: CollisionShape3D = $Collision

func _ready() -> void:
	var capsule := CapsuleShape3D.new()
	capsule.radius = Spec.CAPSULE_RADIUS
	capsule.height = Spec.CAPSULE_HEIGHT
	collision.shape = capsule
	collision.position.y = Spec.CAPSULE_HEIGHT / 2.0      # capsule bottom at the feet
	sprite.height_m = Spec.HEIGHT_M
	for i in range(1, 9):                                    # optional walk cycle: walk_1.png, walk_2.png, ...
		if ResourceLoader.exists(ART_DIR + "walk_%d.png" % i):
			_walk_frames.append(ART_DIR + "walk_%d.png" % i)
	add_child(preload("res://scenes/blob_shadow.gd").new())
	Story.hari_state_changed.connect(_show_state)
	_show_state(Story.hari_state)

func _physics_process(delta: float) -> void:
	var input: Vector2 = Vector2.ZERO if Story.movement_locked() else Controls.move_vector()
	var direction := Vector3.ZERO
	if camera and input != Vector2.ZERO:
		var right := camera.global_basis.x
		var forward := -camera.global_basis.z
		right.y = 0.0
		forward.y = 0.0
		direction = (right.normalized() * input.x + forward.normalized() * -input.y).limit_length(1.0)
		var screen_x := direction.dot(right.normalized())
		if absf(screen_x) > 0.1 and (screen_x < 0.0) != _facing_left:
			_facing_left = screen_x < 0.0                    # art faces right; flip when moving screen-left
			_turn = TURN_SECONDS
	var target_v := direction * Spec.WALK_SPEED
	var rate := ACCEL if target_v.length() > 0.01 else DECEL
	var hv := Vector3(velocity.x, 0.0, velocity.z).move_toward(target_v, rate * delta)
	velocity = Vector3(hv.x, 0.0, hv.z)
	move_and_slide()
	position.y = 0.0
	Story.player_x = global_position.x
	Story.set_moving(direction != Vector3.ZERO)

## Presentation-only motion: walk frames by distance, step bob, idle breathing, turn squash.
func _process(delta: float) -> void:
	_time += delta
	var speed := Vector2(velocity.x, velocity.z).length()
	var k := clampf(speed / Spec.WALK_SPEED, 0.0, 1.0)
	_travel += speed * delta
	var walking := Story.hari_state == "WALK"
	if walking and _walk_frames.size() > 1:
		var frame := int(_travel / STRIDE_M) % _walk_frames.size()
		sprite.set_art(_walk_frames[frame], "walk")
	# low on contact frames (even), high on passing frames (odd): a step, not a float
	var bob := (1.0 - cos(PI * (_travel / STRIDE_M - 0.5))) * 0.5 * BOB_M * k if walking else 0.0
	sprite.position.y = sprite.height_m / 2.0 + bob
	var breath := 1.0 + (sin(_time * TAU * BREATH_HZ) * BREATH_AMOUNT if not walking else 0.0)
	_turn = maxf(_turn - delta, 0.0)
	var squash := 1.0 - 0.55 * sin(PI * (1.0 - _turn / TURN_SECONDS)) if _turn > 0.0 else 1.0
	sprite.flip_h = _facing_left
	sprite.scale = Vector3(squash, breath, 1.0)

func _show_state(state: String) -> void:
	var key := state.to_lower()
	if key == "walk" and _walk_frames.size() > 1:
		sprite.set_art(_walk_frames[int(_travel / STRIDE_M) % _walk_frames.size()], key)
	else:
		sprite.set_art(ART_DIR + key + ".png", key)
	label.text = state
	label.visible = not sprite.has_art                       # state label only on placeholders

extends Node
## Keyboard -> logic. Polls actions with is_action_just_pressed, so a held key or OS
## key-repeat echo can never fire an action twice. Movement (camera-relative) is read
## by the presentation through move_vector(); everything else goes straight to the logic.

const InputSetup = preload("res://logic/input_setup.gd")

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	InputSetup.ensure_actions()

func _process(_delta: float) -> void:
	var ls: Node = get_node("/root/LoopState")
	var story: Node = get_node("/root/Story")
	var sound: Node = get_node("/root/SoundBank")
	if Input.is_action_just_pressed("quit") and ls.is_ended():
		get_tree().quit()
		return
	if Input.is_action_just_pressed("pause") and not ls.is_ended():
		ls.set_paused(not get_tree().paused)
	if Input.is_action_just_pressed("mute_music"):
		sound.toggle_bus_mute("Music")
	if Input.is_action_just_pressed("mute_sfx"):
		sound.toggle_bus_mute("SFX")
	if get_tree().paused:
		return
	ls.fast_forward = Input.is_action_pressed("fast_forward")
	if ls.is_ended() and Input.is_action_just_pressed("restart"):
		ls.begin_slice()
		return
	if Input.is_action_just_pressed("choice_up"):
		story.move_choice(-1)
	if Input.is_action_just_pressed("choice_down"):
		story.move_choice(1)
	if Input.is_action_just_pressed("interact"):
		story.press_interact()

## WASD / arrows as a 2D vector (x = right, y = down/back), for camera-relative movement.
func move_vector() -> Vector2:
	return Input.get_vector("move_left", "move_right", "move_up", "move_down")

extends RefCounted
## Hari's size, collision and movement, in one place (metres). The character sheet references these.

const HEIGHT_M := 1.75              ## sprite image height maps to this (pixel_size = HEIGHT_M / texture height)
const CAPSULE_RADIUS := 0.28
const CAPSULE_HEIGHT := 1.70        ## total capsule height, bottom at the feet (y = 0)
const WALK_SPEED := 2.2             ## m/s on the XZ plane, camera-relative, no jumping
const INTERACT_RANGE := 1.6         ## m (XZ distance) to talk to an NPC
const PLACEHOLDER_PX := Vector2i(96, 216)   ## generated placeholder image size (same 4:9 frame as the art)

extends Node3D
## Builds the simple-box set dressing: railing, pool walls, string-light poles, bulbs and lights.
## Layout numbers (metres) are constants here; the floor and water are textured nodes in the scene.

const Art3D = preload("res://scenes/art3d.gd")
const DECK_LENGTH := 26.0
const DECK_HALF_DEPTH := 4.0
const RAILING_START_X := 20.0
const POOL := Rect2(9.0, -3.2, 7.0, 2.4)      ## x, z, size x, size z (the recess)
const POOL_DEPTH := 0.6
const LIGHT_XS := [6.0, 10.0, 14.0, 18.0]      ## string-light poles along the back of the deck
const LIGHT_Z := -3.6
const STRING_LIGHT_COLOR := Color(1.0, 0.66, 0.36)   ## ~2700 K

func _ready() -> void:
	var rail := Art3D.lit_material(Color("d8cbb5"))
	# railing along the +x end and along +z for the railing zone
	_box(Vector3(0.08, 0.08, DECK_HALF_DEPTH * 2), Vector3(DECK_LENGTH, 1.05, 0), rail)
	_box(Vector3(DECK_LENGTH - RAILING_START_X, 0.08, 0.08), Vector3((DECK_LENGTH + RAILING_START_X) / 2.0, 1.05, DECK_HALF_DEPTH), rail)
	for i in 9:
		_box(Vector3(0.06, 1.05, 0.06), Vector3(DECK_LENGTH, 0.52, -DECK_HALF_DEPTH + i * 1.0), rail)
	for i in 7:
		_box(Vector3(0.06, 1.05, 0.06), Vector3(RAILING_START_X + i * 1.0, 0.52, DECK_HALF_DEPTH), rail)
	# pool walls (the floor has a hole over POOL; water sits below)
	var tile := Art3D.lit_material(Color("8fd3e0"))
	var c := POOL.get_center()
	_box(Vector3(POOL.size.x, POOL_DEPTH, 0.05), Vector3(c.x, -POOL_DEPTH / 2, POOL.position.y), tile)
	_box(Vector3(POOL.size.x, POOL_DEPTH, 0.05), Vector3(c.x, -POOL_DEPTH / 2, POOL.end.y), tile)
	_box(Vector3(0.05, POOL_DEPTH, POOL.size.y), Vector3(POOL.position.x, -POOL_DEPTH / 2, c.y), tile)
	_box(Vector3(0.05, POOL_DEPTH, POOL.size.y), Vector3(POOL.end.x, -POOL_DEPTH / 2, c.y), tile)
	# string lights: poles, a sagging row of emissive bulbs, and a warm OmniLight3D per span
	var pole := Art3D.lit_material(Color("2b2530"))
	var bulb := Art3D.lit_material(Color("ffd36b"), 4.0, Color("ffc46b"))
	for i in LIGHT_XS.size():
		var x: float = LIGHT_XS[i]
		_box(Vector3(0.08, 3.2, 0.08), Vector3(x, 1.6, LIGHT_Z), pole)
		if i + 1 < LIGHT_XS.size():
			var next: float = LIGHT_XS[i + 1]
			for s in range(1, 8):
				var t := s / 8.0
				_sphere(0.06, Vector3(lerpf(x, next, t), 3.1 - sin(t * PI) * 0.45, LIGHT_Z + 0.05), bulb)
			var light := OmniLight3D.new()
			light.light_color = STRING_LIGHT_COLOR
			light.light_energy = 2.8
			light.omni_range = 7.0
			light.position = Vector3((x + next) / 2.0, 2.7, LIGHT_Z + 1.2)
			add_child(light)

func _box(size: Vector3, pos: Vector3, material: Material) -> void:
	var mi := MeshInstance3D.new()
	var mesh := BoxMesh.new()
	mesh.size = size
	mi.mesh = mesh
	mi.position = pos
	mi.material_override = material
	add_child(mi)

func _sphere(radius: float, pos: Vector3, material: Material) -> void:
	var mi := MeshInstance3D.new()
	var mesh := SphereMesh.new()
